import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/index.md","filePath":"concepts/index.md"}'),n={name:"concepts/index.md"};function i(r,e,c,l,d,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>CCattler takes a fundamentally different approach to container orchestration. Instead of managing mutable API objects (Pods, Deployments, ReplicaSets), CCattler operates on <strong>facts</strong> — immutable observations about what the world should look like and what it actually looks like.</p><h2 id="core-ideas" tabindex="-1">Core ideas <a class="header-anchor" href="#core-ideas" aria-label="Permalink to &quot;Core ideas&quot;">​</a></h2><h3 id="facts-not-objects" tabindex="-1">Facts, not objects <a class="header-anchor" href="#facts-not-objects" aria-label="Permalink to &quot;Facts, not objects&quot;">​</a></h3><p>The cluster stores key-value facts in etcd, organized into three namespaces:</p><ul><li><strong><code>desired/</code></strong> — what the world should look like (written by users and policy controllers)</li><li><strong><code>observed/</code></strong> — what the world actually looks like (written by node agents)</li><li><strong><code>placement/</code></strong> — scheduling decisions (written by the scheduler)</li></ul><p>The gap between <code>desired/</code> and <code>observed/</code> is the work. Controllers close that gap continuously.</p><h3 id="no-yaml" tabindex="-1">No YAML <a class="header-anchor" href="#no-yaml" aria-label="Permalink to &quot;No YAML&quot;">​</a></h3><p>CCattler uses a purpose-built domain language instead of YAML. You declare intent — the system figures out the implementation:</p><div class="language-hcl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hcl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> web</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    image nginx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.28</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    instances </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    expose </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This compiles to facts: <code>service(name=&quot;web&quot;, image=&quot;nginx:1.28&quot;, instances=3)</code>, <code>exposes(service=&quot;web&quot;, port=8080)</code>.</p><h3 id="everything-communicates-through-state" tabindex="-1">Everything communicates through state <a class="header-anchor" href="#everything-communicates-through-state" aria-label="Permalink to &quot;Everything communicates through state&quot;">​</a></h3><p>No component calls another component directly. The scheduler writes a placement fact; the node agent notices it. The agent starts a container and writes an observed state fact; the endpoint controller notices it. This makes the system naturally resilient — any component can crash and restart without breaking the others.</p><h2 id="kubernetes-comparison" tabindex="-1">Kubernetes comparison <a class="header-anchor" href="#kubernetes-comparison" aria-label="Permalink to &quot;Kubernetes comparison&quot;">​</a></h2><p>If you know Kubernetes, here&#39;s how CCattler maps:</p><table tabindex="0"><thead><tr><th>Kubernetes</th><th>CCattler</th><th>Key difference</th></tr></thead><tbody><tr><td>Cluster</td><td>Fact Store + Agents</td><td>No explicit cluster object — nodes register by writing facts</td></tr><tr><td>Pod</td><td>Instance + Group</td><td>An instance is one container; groups share network/volumes</td></tr><tr><td>Deployment / ReplicaSet</td><td>Service fact + Instance controller</td><td><code>desired=5, actual=3</code> → create 2 more. No object chain</td></tr><tr><td>Control Plane</td><td>Runner + Controllers + Store</td><td>Controllers are stateless rule engines, not resource managers</td></tr><tr><td>Reconciliation loop</td><td><code>facts → controllers → changes → agents → observations → repeat</code></td><td>Single loop for all capabilities</td></tr><tr><td>Taints/Tolerations</td><td><code>restrict</code> / <code>accept</code></td><td>Human-readable placement constraints</td></tr><tr><td>Affinity/Anti-affinity</td><td><code>require</code> / <code>prefer</code></td><td>Direct label matching, no complex expressions</td></tr></tbody></table><h2 id="learn-more" tabindex="-1">Learn more <a class="header-anchor" href="#learn-more" aria-label="Permalink to &quot;Learn more&quot;">​</a></h2><ul><li><a href="/concepts/facts">Facts &amp; State</a> — the fact-based state model</li><li><a href="/concepts/reconciliation">Reconciliation</a> — how the loop works</li><li><a href="/concepts/controllers">Controllers</a> — rule engines that close the gap</li><li><a href="/concepts/networking">Networking</a> — service discovery, VIPs, DNS</li><li><a href="/concepts/security">Security</a> — zero-trust security model</li></ul>`,18)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
